{"content":"// TypeScript Logic & Interface Test
// Defines a Product interface and demonstrates array manipulation

interface Product {
  name: string;
  price: number;
  category: string;
}

// Initialize array of 5 products
const products: Product[] = [
  { name: "Laptop", price: 999.99, category: "Electronics" },
  { name: "Headphones", price: 49.99, category: "Electronics" },
  { name: "Coffee Maker", price: 79.99, category: "Kitchen" },
  { name: "Desk Lamp", price: 24.99, category: "Home" },
  { name: "Notebook Set", price: 12.99, category: "Office" }
];

// Filter function for items < $50
function filterUnderBudget(products: Product[], budget: number): Product[] {
  return products.filter(product => product.price < budget);
}

// Execute and log results
const filteredProducts = filterUnderBudget(products, 50);

console.log("=== TypeScript Logic & Interface Test ===");
console.log("Total products: ", products.length);
console.log("Products under $50: ", filteredProducts.length);
console.log("\nFiltered Product List:");
console.log("----------------------");
filteredProducts.forEach(product => {
  console.log(`- ${product.name}: $${product.price.toFixed(2)} (${product.category})`);
});
","path":"ts-logic-test/app.ts"}

